import json,numpy as np
m=json.load(open('/app/output/initial/meta.json'))
pts={'front':(155,125),'left':(155,120),'right':(164,124)}
for cam,(u,v) in pts.items():
 T=np.array(m['cameras'][cam]['cam2world_gl']);K=np.array(m['cameras'][cam]['intrinsic_cv']);D=np.load('/app/output/initial/depth_'+cam+'.npy')[0]
 print(cam,'depth',[(uu,vv,float(D[vv,uu])) for uu,vv in [(u,v),(u-3,v),(u+3,v),(u,v-3),(u,v+3)]])
 for mode in [0,1]:
  z=float(D[v,u]);pt=np.linalg.inv(K)@np.array([u,v,1]);pt=pt*z/(np.linalg.norm(pt) if mode else 1);wpt=T[:3,:3]@np.diag([1,-1,-1])@pt+T[:3,3];print(mode,wpt)
